def get_packages_data(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package

    Returns
    -------
    dict
    """
    packages_data = {}
    for file in os.listdir(folder):
        if file.endswith(".xml"):
            package_name = os.path.splitext(file)[0]
            if package_name not in packages_data:
                packages_data[package_name] = {}
            with open(os.path.join(folder, file)) as f:
                data = xmltodict.parse(f.read())
                for k, v in data["documentElement"].items():
                    packages_data[package_name][k] = v
    return packages_data

