def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """

    # Initialize an empty dictionary to store the combined values
    combined = {}

    # Iterate over the iterable of dictionaries
    for d in dicts:
        # Iterate over the key-value pairs in the current dictionary
        for k, v in d.items():
            # If the key is already present in the combined dictionary, add the value to the existing one
            if k in combined:
                combined[k] += v
            # Otherwise, simply set the value of the key in the combined dictionary
            else:
                combined[k] = v

    return combined

