def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Check if explicit metaclass is given and valid (only one can be given)
    if explicit_mc is not None:
        if len(bases) > 1:
            raise ValueError("Explicit __metaclass__ found, cannot set metaclass with multiple bases")
        return explicit_mc

    # If there are multiple bases, check if any of them have a metaclass
    if len(bases) > 1:
        for base in bases:
            if getattr(base, "__metaclass__", None) is not None:
                return base.__metaclass__

        # No metaclass found in bases, use default metaclass
        return METACLASS_DEFAULT

    # If there is only one base without a metaclass, use its metaclass
    elif len(bases) == 1 and getattr(bases[0], "__metaclass__", None) is None:
        return bases[0].__metaclass__

    # No explicit metaclass or metaclass in base, use default metaclass
    return METACLASS_DEFAULT

def pop(self, key, default=None):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is not None:
            return default
        raise KeyError(key)
    for map in [self._pb.IntMap, self._pb.FloatMap, self._pb.StringMap,
                self._pb.BoolMap]:
        if key in map.keys():
            return map.pop(key)

