def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """

    code_block_tags = {
        'tags': set(),
        'indices': [],
    }

    tags = set()
    new_text = ''

    in_code_block = False
    for i, line in enumerate(text.split('\n')):
        try:
            if in_code_block and _is_code_block_tag(line):
                if _is_code_block_end_tag(line):
                    in_code_block = False
                continue
            tags.update(_get_tags_from_line(line))
            new_line = line
            if replacer:
                new_line = replacer(line)
            new_text += '{}\n'.format(new_line)
        except Exception:
            pass
        if _is_code_block_start_tag(line):
            in_code_block = True

    return tags, new_text

