def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    signed_nodes = doc.xpath('//soap:Envelope/*/wsse:Security/ds:Signature', namespaces={
        'soap': 'http://www.w3.org/2003/05/soap-envelope/',
        'wsse': 'http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-secext-1.0.xsd',
        'ds': 'http://www.w3.org/2000/09/xmldsig#'
    })

    signed_text = ''.join(signed_nodes)

    signature_obj = ds.Signature.from_string(signature, validation_context=ds.ValidationContext(
        trusted_certs=[public_key],
        c14n_algorithm='http://www.w3.org/TR/2001/REC-xml-c14n-20010315'
    ))

    verified = ds.validate_signature(signed_text, signature_obj, validation_context=ds.ValidationContext(
        trusted_certs=[public_key],
        c14n_algorithm='http://www.w3.org/TR/2001/REC-xml-c14n-20010315'
    ))

    if verified:
        print(f'Signature verified successfully for signed_text={signed_text} and signature_obj={signature_obj}')
    else:
        raise ValueError(f'Signature verification failed for signed_text={signed_text} and signature_obj={signature_obj}')

def parse_diaspora_webfinger(document: str) -> Dict:
    # Convert the document to a JSON object
    try:
        json_obj = json.loads(document)
    except ValueError:
        # If the document is not in JSON format, try to parse it as an XRD
        xrds = ExpatParser().Parse(document)
        # Look for the first Link element with the rel "lrdd"
        for link in xrds.getElementsByTagName("Link"):
            if link.get("rel") == "lrdd":
                # Replace the {uri} placeholder with the handle
                href = link.getAttribute("template").replace("{uri}", quote(handle))
                # Get the document from the href URL
                document, code, exception = fetch_document(url=href)
                if document:
                    json_obj = json.loads(document)
                    break

    if not json_obj:
        raise ValueError("Invalid Diaspora webfinger document")

    # Parse the JSON object into a dict
    webfinger = dict()
    for key, value in json_obj.items():
        webfinger[key] = value

    # Return the parsed webfinger dict
    return webfinger

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    headers = CaseInsensitiveDict({
        'User-Agent': USER_AGENT,
    })
    if "headers" in kwargs:
        # Update from kwargs
        headers.update(kwargs.get("headers"))
    kwargs.update({
        "data": data, "timeout": timeout, "headers": headers
    })
    try:
        if method.lower() == "post":
            response = requests.post(url, *args, **kwargs)
        elif method.lower() == "get":
            response = requests.get(url, *args, **kwargs)
        else:
            raise ValueError(f"Invalid method {method}, must be POST or GET")
        logger.debug("send_document: response status code %s", response.status_code)
        return response.status_code, None
    except RequestException as ex:
        logger.debug("send_document: exception %s", ex)
        return None, ex

