        Returns:
            dict: A dictionary of argument values, with keys matching the argument names.
        """
        defaults = {}
        for arg in self.args:
            if isinstance(arg, Option):
                # if there is a default set in the spec, use that
                if arg.spec is not None and arg.spec.default is not None:
                    defaults[arg.name] = arg.spec.default
